CREATE TABLE IF NOT EXISTS jwt_session ( user_session_id VARCHAR(36) NOT NULL, username VARCHAR(200) NOT NULL, user_source VARCHAR(200) NOT NULL, revoked_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, type VARCHAR(32) NOT NULL DEFAULT 'SESSION',
CONSTRAINT pk_jwt_session_user_session_id PRIMARY KEY (user_session_id) );
-- INDEX idx_jwt_session_expires provided by JwtSessionIndexMigrationStep_2_103

INSERT INTO jwt_session (user_session_id, username, user_source, revoked_at, expires_at, type)
VALUES (#{session.userSessionId}, #{session.username}, #{session.userSource},
        #{session.revokedAt}, #{session.expiresAt}, 'USER_INVALIDATION');

mapper.select:
SELECT EXISTS(
  SELECT 1 FROM jwt_session
  WHERE user_session_id = #{userSessionId}
    AND type = 'SESSION'
);

SELECT EXISTS(
  SELECT 1 FROM jwt_session
  WHERE user_session_id = #{userSessionId}
);

SELECT EXISTS(
  SELECT 1 FROM jwt_session
  WHERE type = 'USER_INVALIDATION'
    AND username = #{username}
    AND revoked_at > #{iat}
);
